import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s6-u10")
C = "B1-B2"
# Lições de aprofundamento (10–25): construção da frase.

def X(id, nl, pt, pos="expression"): return V(id, nl, pt, pos)

L(10, "Modais no passado composto", "Ik had willen komen.",
  ["Usar modais no perfeito e no mais-que-perfeito com duplo infinitivo"],
  vocab=[X("v-had-willen","had willen","teria querido|queria ter"), X("v-heeft-moeten","heeft moeten","teve de")],
  ex=[("Ik had graag willen komen, maar ik was ziek.","Teria gostado de vir, mas estava doente."),("Hij heeft lang moeten wachten.","Ele teve de esperar muito tempo."),("We hebben het niet kunnen vinden.","Não o conseguimos encontrar.")],
  review=["v-had-kunnen","v-had-moeten","v-werkwoordscluster"],
  gram=[G("g-modaal-perfectum","Modal no perfeito","No perfeito, o modal fica no **infinitivo** (não particípio) e vai para o fim junto do outro verbo: *Ik heb moeten werken* (não ~~gemoeten~~). Chama-se **duplo infinitivo**. Na subordinada: *…dat ik heb moeten werken*.",
    [("Ze heeft niet kunnen komen.","Ela não pôde vir."),("Ik had het willen zeggen.","Eu queria tê-lo dito.")])],
  cefr=C, exs=[
    MA([("had willen","teria querido"),("heeft moeten","teve de"),("had kunnen","podia ter"),("had moeten","devia ter")], "Modais.", ["v-had-willen","v-heeft-moeten","v-had-kunnen","v-had-moeten"]),
    MC("Ela não pôde vir:", ["*Ze heeft niet kunnen komen.","Ze heeft niet gekund komen.|Sem particípio.","Ze is niet kunnen komen.|Auxiliar: hebben."], "Duplo infinitivo.", ["v-heeft-moeten"]),
    TR("pt-nl","Ele teve de esperar muito.", ["Hij heeft lang moeten wachten"], "Duplo infinitivo.", ["v-heeft-moeten"]),
    TR("pt-nl","Teria gostado de vir.", ["Ik had graag willen komen","Ik was graag gekomen"], "had willen.", ["v-had-willen"]),
    CJ("kunnen","we","We hebben het niet ___ vinden.", ["kunnen"], "Infinitivo, não particípio.", ["v-heeft-moeten"], tense="passado-perfeito"),
    FE(["Ik","heb","gisteren","moeten","gewerkt."], 4, "werken.", "Duplo infinitivo: moeten werken.", ["v-heeft-moeten"]),
    FE(["Ze","heeft","niet","gekund","komen."], 3, "kunnen", "Modal no infinitivo.", ["v-heeft-moeten"]),
    LI("Ik had het je eerder willen vertellen.", ["Ik had het je eerder willen vertellen"], "Queria ter-te contado mais cedo.", "Arrependimento.", ["v-had-willen"]),
    WO("Ele teve de esperar.", ["Hij","heeft","moeten","wachten"], "Ordem.", ["v-heeft-moeten"]),
  ], diff=5, mins=6)

L(11, "Ver e ouvir alguém fazer", "Ik zag hem komen.",
  ["Usar zien e horen com infinitivo"],
  vocab=[X("v-zien-doen","iemand iets zien doen","ver alguém fazer algo"), X("v-horen-doen","iemand iets horen doen","ouvir alguém fazer algo")],
  ex=[("Ik zag hem de straat oversteken.","Vi-o atravessar a rua."),("We hoorden de buren ruziemaken.","Ouvimos os vizinhos a discutir."),("Ik heb haar nog nooit horen zingen.","Nunca a ouvi cantar.")],
  review=["v-zien","v-horen"],
  cefr=C, exs=[
    MA([("iemand iets zien doen","ver alguém fazer"),("iemand iets horen doen","ouvir alguém fazer"),("zien","ver"),("horen","ouvir")], "Perceção.", ["v-zien-doen","v-horen-doen","v-zien","v-horen"]),
    MC("No perfeito: «Nunca a ouvi cantar»:", ["*Ik heb haar nog nooit horen zingen.","Ik heb haar nog nooit gehoord zingen.|Duplo infinitivo.","Ik heb haar nooit zingen gehoord.|Não."], "Duplo infinitivo.", ["v-horen-doen"]),
    TR("pt-nl","Vi-o atravessar a rua.", ["Ik zag hem de straat oversteken"], "zien + infinitivo.", ["v-zien-doen"]),
    TR("pt-nl","Ouvimos os vizinhos a discutir.", ["We hoorden de buren ruziemaken","We hoorden de buren ruzie maken","Wij hoorden de buren ruziemaken"], "horen + infinitivo.", ["v-horen-doen"]),
    FB("Ik heb de kinderen in de tuin ___ spelen.", ["zien"], "Duplo infinitivo.", ["v-zien-doen"], choices=["zien","gezien","zag"], tr="Vi as crianças a brincar no jardim."),
    FE(["Ik","zag","hem","komt."], 3, "komen.", "zien + infinitivo.", ["v-zien-doen"]),
    LI("Heb je de bel horen gaan?", ["Heb je de bel horen gaan","Heb je de bel horen gaan?"], "Ouviste a campainha tocar?", "Uso.", ["v-horen-doen"]),
    MC("«Ik voel de vloer trillen» segue a mesma regra porque…", ["*«voelen» também é verbo de perceção","é um erro|Não.","é futuro|Não."], "Perceção.", ["v-zien-doen"]),
    WO("Vi-o chegar.", ["Ik","zag","hem","komen"], "Ordem.", ["v-zien-doen"]),
  ], diff=5, mins=5)

L(12, "Mandar fazer: laten", "Ik laat mijn fiets repareren.",
  ["Usar laten para mandar fazer algo"],
  vocab=[X("v-laten-causaal","laten + infinitivo","mandar fazer|deixar fazer"), X("v-laten-nakijken","laten nakijken","mandar verificar","verb")],
  ex=[("Ik laat mijn fiets repareren.","Vou mandar arranjar a bicicleta."),("Ze heeft haar haar laten knippen.","Ela foi cortar o cabelo (mandou cortar)."),("Laat je auto voor de vakantie nakijken.","Manda verificar o carro antes das férias.")],
  review=["v-laten-repareren","v-laten-knippen","v-laten-maken","v-laten-zien"],
  gram=[G("g-laten-causatief","Laten = mandar fazer","**Laten + infinitivo** significa que outra pessoa faz a ação por nós: *Ik laat mijn haar knippen* (o cabeleireiro corta). No perfeito: duplo infinitivo — *Ik heb mijn haar laten knippen*. Também pode significar «deixar»: *Laat hem maar slapen.*",
    [("We hebben een nieuwe keuken laten plaatsen.","Mandámos instalar uma cozinha nova."),("Laat me even nadenken.","Deixa-me pensar.")])],
  cefr=C, exs=[
    MA([("laten + infinitivo","mandar fazer"),("laten nakijken","mandar verificar"),("laten repareren","mandar arranjar"),("je haar laten knippen","ir cortar o cabelo")], "Laten.", ["v-laten-causaal","v-laten-nakijken","v-laten-repareren","v-laten-knippen"]),
    MC("«Ik knip mijn haar» vs. «Ik laat mijn haar knippen»:", ["*eu próprio corto vs. alguém corta por mim","iguais|Não.","passado vs. presente|Não."], "Causativo.", ["v-laten-causaal"]),
    TR("pt-nl","Vou mandar arranjar a bicicleta.", ["Ik laat mijn fiets repareren","Ik ga mijn fiets laten repareren"], "laten.", ["v-laten-repareren"]),
    TR("pt-nl","Ela foi cortar o cabelo.", ["Ze heeft haar haar laten knippen","Zij heeft haar haar laten knippen"], "Duplo infinitivo.", ["v-laten-knippen"]),
    FB("We hebben een nieuwe badkamer laten ___.", ["plaatsen"], "Infinitivo.", ["v-laten-causaal"], choices=["plaatsen","geplaatst","plaatst"], tr="Mandámos instalar uma casa de banho nova."),
    FE(["Ik","heb","mijn","auto","gelaten","nakijken."], 4, "laten", "Duplo infinitivo: laten nakijken.", ["v-laten-nakijken"]),
    DL([("Collega","Heb je zelf je huis geschilderd?","Pintaste tu a casa?"),("Jij","","")], ["*Nee, ik heb het laten doen; ik heb er geen tijd voor.","Ja, ik laat schilderen.|Contraditório.","Laten nakijken.|Sem sentido."], "Causativo.", ["v-laten-causaal"]),
    LI("Laat je ogen regelmatig controleren.", ["Laat je ogen regelmatig controleren"], "Manda verificar os olhos regularmente.", "Conselho.", ["v-laten-causaal"]),
    WO("Mandei arranjar a bicicleta.", ["Ik","heb","mijn","fiets","laten","repareren"], "Ordem.", ["v-laten-repareren"]),
  ], diff=4, mins=6)

L(13, "Onde fica o «niet»?", "Ik heb hem niet gezien.",
  ["Colocar niet corretamente e usar negações enfáticas"],
  vocab=[X("v-helemaal-niet","helemaal niet","nada|de todo"), X("v-allerminst","allerminst","de modo nenhum|nada mesmo","adverb")],
  ex=[("Ik ben helemaal niet moe.","Não estou nada cansado."),("Hij is allerminst tevreden.","Ele não está nada satisfeito."),("Ik heb hem gisteren niet gezien.","Não o vi ontem.")],
  review=["v-niet-meer","v-nog-niet"],
  gram=[G("g-plaats-niet","Posição de niet","Regra geral: **niet** vem **depois** do objeto direto definido e das expressões de tempo, mas **antes** de adjetivos, preposições, advérbios de modo e da parte separável/infinitivo/particípio no fim. *Ik zie hem niet.* · *Ik ben niet moe.* · *Ik ga niet naar huis.* · *Ik heb het niet gedaan.* Para negar a frase toda, fica o mais tarde possível.",
    [("Hij komt morgen niet.","Ele não vem amanhã."),("Ze woont niet in Utrecht.","Ela não vive em Utrecht.")])],
  cefr=C, exs=[
    MA([("helemaal niet","de todo"),("allerminst","de modo nenhum"),("niet meer","já não"),("nog niet","ainda não")], "Negação.", ["v-helemaal-niet","v-allerminst","v-niet-meer","v-nog-niet"]),
    MC("Qual está correto?", ["*Ik heb het boek niet gelezen.","Ik heb niet het boek gelezen.|Objeto definido antes de niet.","Ik niet heb het boek gelezen.|Não."], "Posição.", ["v-helemaal-niet"]),
    MC("Qual está correto?", ["*Ze woont niet in Amsterdam.","Ze woont in Amsterdam niet.|Antes da preposição.","Ze niet woont in Amsterdam.|Não."], "Antes da preposição.", ["v-helemaal-niet"]),
    TR("pt-nl","Não estou nada cansado.", ["Ik ben helemaal niet moe","Ik ben totaal niet moe"], "helemaal niet.", ["v-helemaal-niet"]),
    TR("pt-nl","Não o vi ontem.", ["Ik heb hem gisteren niet gezien","Gisteren heb ik hem niet gezien"], "Depois do tempo.", ["v-helemaal-niet"]),
    MC("Qual é a ordem correta?", ["*Hij komt morgen niet.","Hij komt niet morgen.|Tempo antes de niet: Hij komt morgen niet."], "Tempo antes de niet: Hij komt morgen niet.", ["v-helemaal-niet"]),
    FB("De minister was ___ blij met de kritiek.", ["allerminst"], "Formal enfático.", ["v-allerminst"], choices=["allerminst","helemaal","minst"], tr="O ministro não ficou nada contente com as críticas."),
    LI("Dat is helemaal niet wat ik bedoelde.", ["Dat is helemaal niet wat ik bedoelde"], "Isso não é nada o que eu queria dizer.", "Uso.", ["v-helemaal-niet"]),
    WO("Ela não vive em Utrecht.", ["Ze","woont","niet","in","Utrecht"], "Ordem.", ["v-helemaal-niet"]),
  ], diff=5, mins=6)

L(14, "Tempo – modo – lugar", "Ik ga morgen met de trein naar Utrecht.",
  ["Ordenar complementos de tempo, modo e lugar"],
  vocab=[X("v-tijd-manier-plaats","tijd – manier – plaats","tempo – modo – lugar (ordem)")],
  ex=[("Ik ga morgen met de trein naar Utrecht.","Amanhã vou de comboio para Utrecht."),("Ze fietst elke dag samen met haar zus naar school.","Ela vai todos os dias de bicicleta com a irmã para a escola.")],
  review=["v-nauwkeurig-volgorde"],
  gram=[G("g-tmp","Tempo – Modo – Lugar","Quando há vários complementos, a ordem habitual é **Tempo → Modo → Lugar**: *Ik ga **morgen** (T) **met de trein** (M) **naar Utrecht** (L).* Qualquer um pode ir para o início para dar ênfase — e então o verbo vem logo a seguir: *Morgen ga ik met de trein naar Utrecht.*",
    [("We eten vanavond gezellig thuis.","Hoje à noite jantamos tranquilamente em casa."),("Hij werkt sinds maart hard in de haven.","Desde março ele trabalha muito no porto.")])],
  cefr=C, exs=[
    MA([("morgen","tempo"),("met de trein","modo"),("naar Utrecht","lugar"),("tijd – manier – plaats","ordem T-M-L")], "TML.", ["v-tijd-manier-plaats","v-nauwkeurig-volgorde","v-tijd-manier-plaats"]),
    MC("Qual é a ordem mais natural?", ["*Ik ga morgen met de bus naar het werk.","Ik ga naar het werk met de bus morgen.|Lugar antes do tempo.","Ik ga met de bus naar het werk morgen.|Tempo no fim."], "T-M-L.", ["v-tijd-manier-plaats"]),
    TR("pt-nl","Amanhã vou de comboio para Utrecht.", ["Ik ga morgen met de trein naar Utrecht","Morgen ga ik met de trein naar Utrecht"], "T-M-L.", ["v-tijd-manier-plaats"]),
    TR("pt-nl","Hoje à noite jantamos em casa.", ["We eten vanavond thuis","Vanavond eten we thuis","Wij eten vanavond thuis"], "T-L.", ["v-tijd-manier-plaats"]),
    WO("Ela vai todos os dias de bicicleta para a escola.", ["Ze","fietst","elke","dag","samen","met","haar","zus","naar","school"], "T-M-L.", ["v-tijd-manier-plaats"]),
    MC("Qual é a ordem correta?", ["*Ik ga morgen met de trein naar Utrecht.","Ik ga naar Utrecht morgen met de trein.|Tempo primeiro: Ik ga morgen met de trein naar Utrecht."], "Tempo primeiro: Ik ga morgen met de trein naar Utrecht.", ["v-tijd-manier-plaats"]),
    BS("Amanhã vamos de carro à praia.", ["We","gaan","morgen","met","de","auto","naar","het","strand"], ["We gaan morgen met de auto naar het strand"], "T-M-L.", ["v-tijd-manier-plaats"]),
    LI("Hij werkt sinds maart met veel plezier in de haven.", ["Hij werkt sinds maart met veel plezier in de haven"], "Desde março ele trabalha com muito gosto no porto.", "T-M-L.", ["v-tijd-manier-plaats"]),
  ], diff=4, mins=5)

L(15, "Começar pela subordinada", "Omdat het regende, bleven we thuis.",
  ["Pôr a oração subordinada no início e inverter a principal"],
  vocab=[X("v-subordinada-eerst","bijzin vooraan","subordinada à frente")],
  ex=[("Omdat het regende, bleven we thuis.","Como chovia, ficámos em casa."),("Aangezien je er toch bent, kun je helpen.","Já que estás cá, podes ajudar."),("Als je klaar bent, mag je gaan.","Quando acabares, podes ir.")],
  review=["v-aangezien","v-omdat","v-zodra"],
  gram=[G("g-bijzin-vooraan","Subordinada no início","Se a frase começa com uma **subordinada**, esta ocupa a 1.ª posição; por isso a oração principal começa **com o verbo**: *Omdat het regende, **bleven** we thuis.* Padrão: *[bijzin], verbo – sujeito – resto.*",
    [("Toen ik thuiskwam, was iedereen weg.","Quando cheguei a casa, já não estava ninguém."),("Hoewel het duur is, koop ik het.","Embora seja caro, compro-o.")])],
  cefr=C, exs=[
    MA([("omdat","porque"),("aangezien","visto que"),("zodra","assim que"),("bijzin vooraan","subordinada à frente")], "Conectores.", ["v-omdat","v-aangezien","v-zodra","v-subordinada-eerst"]),
    MC("Qual está correto?", ["*Omdat het regende, bleven we thuis.","Omdat het regende, we bleven thuis.|Falta a inversão.","Omdat regende het, bleven we thuis.|Ordem errada na subordinada."], "Inversão.", ["v-subordinada-eerst"]),
    TR("pt-nl","Como chovia, ficámos em casa.", ["Omdat het regende, bleven we thuis","Omdat het regende bleven we thuis","Doordat het regende, bleven we thuis"], "Inversão.", ["v-subordinada-eerst"]),
    TR("pt-nl","Já que estás cá, podes ajudar.", ["Aangezien je er toch bent, kun je helpen","Aangezien je er bent, kun je helpen"], "aangezien.", ["v-aangezien"]),
    FB("Zodra de trein stopt, ___ we uit.", ["stappen"], "Inversão: verbo primeiro.", ["v-zodra"], choices=["stappen","we stappen","stapt"], tr="Assim que o comboio parar, saímos."),
    MC("Qual é a ordem correta?", ["*Als je klaar bent, mag je gaan.","Als je klaar bent, je mag gaan.|Inversão: …, mag je gaan."], "Inversão: …, mag je gaan.", ["v-subordinada-eerst"]),
    BS("Embora seja caro, compro-o.", ["Hoewel","het","duur","is,","koop","ik","het"], ["Hoewel het duur is, koop ik het","Hoewel het duur is koop ik het"], "Inversão.", ["v-subordinada-eerst"]),
    LI("Toen ik in Nederland aankwam, sprak ik nog geen woord Nederlands.", ["Toen ik in Nederland aankwam, sprak ik nog geen woord Nederlands","Toen ik in Nederland aankwam sprak ik nog geen woord Nederlands"], "Quando cheguei aos Países Baixos, ainda não falava uma palavra de neerlandês.", "Narração.", ["v-subordinada-eerst"]),
    WO("Quando acabares, podes ir.", ["Als","je","klaar","bent,","mag","je","gaan"], "Inversão.", ["v-subordinada-eerst"]),
  ], diff=4, mins=6)

L(16, "Verbos com te", "Hij weigert te betalen.",
  ["Usar verbos seguidos de te + infinitivo"],
  vocab=[X("v-weigeren","weigeren","recusar(-se)","verb"), X("v-dreigen","dreigen","ameaçar","verb"),
         X("v-proberen-te","proberen te","tentar","verb")],
  ex=[("Hij weigert de boete te betalen.","Ele recusa-se a pagar a multa."),("De rivier dreigt te overstromen.","O rio ameaça transbordar."),("Ik probeer elke dag Nederlands te spreken.","Tento falar neerlandês todos os dias.")],
  review=["v-beloven","v-vergeten","v-durven"],
  gram=[G("g-te-infinitief","Verbos + te + infinitivo","Muitos verbos pedem **te + infinitivo**: *proberen, beginnen, weigeren, beloven, vergeten, dreigen, hopen*. Os modais (*kunnen, moeten, willen, mogen*) **não** levam *te*. *Durven* e *hoeven* aceitam os dois (*hoeven* quase sempre com *te* em frases negativas: *Je hoeft niet te komen*).",
    [("Ze begon te huilen.","Ela começou a chorar."),("Je hoeft niet te betalen.","Não tens de pagar.")])],
  cefr=C, exs=[
    MA([("weigeren","recusar"),("dreigen","ameaçar"),("proberen te","tentar"),("beloven","prometer")], "Verbos + te.", ["v-weigeren","v-dreigen","v-proberen-te","v-beloven"]),
    MC("Qual NÃO leva «te»?", ["*Ik kan … zwemmen","Ik probeer … zwemmen|Leva te.","Ik begin … zwemmen|Leva te."], "Modais sem te.", ["v-proberen-te"]),
    TR("pt-nl","Ele recusa-se a pagar.", ["Hij weigert te betalen"], "weigeren te.", ["v-weigeren"]),
    TR("pt-nl","O rio ameaça transbordar.", ["De rivier dreigt te overstromen","De rivier dreigt buiten haar oevers te treden"], "dreigen te.", ["v-dreigen"]),
    FB("Je hoeft morgen niet ___ komen.", ["te"], "hoeven niet te.", ["v-proberen-te"], choices=["te","om","-"], tr="Não precisas de vir amanhã."),
    FE(["Hij","belooft","op","tijd","komen."], 4, "te komen.", "beloven + te.", ["v-beloven"]),
    FE(["Ik","kan","goed","zwemt."], 3, "zwemmen.", "Depois de kan: infinitivo (sem te).", ["v-proberen-te"]),
    LI("Vergeet niet de deur op slot te doen.", ["Vergeet niet de deur op slot te doen"], "Não te esqueças de trancar a porta.", "vergeten te.", ["v-vergeten"]),
    WO("Tento falar neerlandês.", ["Ik","probeer","Nederlands","te","spreken"], "Ordem.", ["v-proberen-te"]),
  ], diff=4, mins=5)

