  ex=[("Ik ga vroeg slapen, omdat ik morgen vroeg op moet staan.","Vou dormir cedo porque amanhã tenho de me levantar cedo."),("Weet je of hij al is aangekomen?","Sabes se ele já chegou?"),("Ik hoop dat de film snel begint.","Espero que o filme comece depressa.")],
